-- 459: Original BrillaPrep WASSCE Integrated Science Soil and crop production practice questions (batch wassce-int-science-sprint2-001).
-- Curriculum-aligned practice content; not official WAEC examination material.
PRAGMA foreign_keys = ON;
CREATE TABLE _migration_459_expected (id TEXT PRIMARY KEY, topic_id TEXT, subject_id TEXT, exam_type_id TEXT, paper_type_id TEXT, past_paper_id TEXT, question_text TEXT, question_type TEXT, round_type TEXT, options TEXT, correct_answer TEXT, explanation TEXT, difficulty TEXT, points INTEGER, marks INTEGER, time_limit INTEGER, question_number INTEGER, section TEXT, is_compulsory INTEGER, image_url TEXT, syllabus_topic_id TEXT, command_word TEXT, assessment_objective TEXT, source_paper_code TEXT, source_question_number TEXT, exam_board_id TEXT);
INSERT INTO _migration_459_expected (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_wisc_agr_b002_009', 'topic_wassce_p2_sci_agr', 'subj_wassce_int_science', 'exam_wassce', NULL, NULL, 'A soil test on a farm reads pH 4.8 and the crops grow poorly. Which treatment is most appropriate, and why?', 'multiple_choice', NULL, '["A. Apply agricultural lime such as calcium hydroxide to raise the soil pH","B. Apply ammonium sulfate fertilizer to supply more nitrogen","C. Water the field continuously to dilute the acidity","D. Add only fresh acidic compost to feed the crops"]', 'A', 'Acidic soils are corrected by liming: calcium hydroxide neutralises excess hydrogen ions and raises the pH toward the range of about 5.5 to 7 that most food crops prefer. Ammonium sulfate is acid-forming and would worsen the problem, and dilution by watering cannot remove the reserve acidity held on clay and humus particles. Therefore the correct answer is A: Apply agricultural lime such as calcium hydroxide to raise the soil pH.', 'hard', '3', '1', '45', NULL, NULL, '1', NULL, NULL, 'Apply', 'AO3', NULL, NULL, NULL),
('q_wisc_agr_b002_010', 'topic_wassce_p2_sci_agr', 'subj_wassce_int_science', 'exam_wassce', NULL, NULL, 'In a waterlogged clay soil, crop roots often die mainly because', 'multiple_choice', NULL, '["A. the standing water makes the soil too cold for enzymes","B. the air spaces fill with water, so roots cannot obtain oxygen for respiration","C. the excess water dissolves all the humus immediately","D. the roots absorb dangerously large amounts of nitrogen"]', 'B', 'Roots respire aerobically, taking oxygen from soil air spaces. When water fills those spaces, oxygen diffusion to the roots stops; the roots switch to anaerobic respiration, accumulate toxic products and die, so the shoot wilts even though water is abundant. Cold, instant humus loss and nitrogen overload are not the cause. Therefore the correct answer is B: the air spaces fill with water, so roots cannot obtain oxygen for respiration.', 'hard', '3', '1', '45', NULL, NULL, '1', NULL, NULL, 'Explain', 'AO3', NULL, NULL, NULL),
('q_wisc_agr_b002_011', 'topic_wassce_p2_sci_agr', 'subj_wassce_int_science', 'exam_wassce', NULL, NULL, 'A school maize plot measures 40 m by 25 m. Maize is planted at a spacing of 1 m between rows and 0.5 m between plants within a row. Calculate the expected plant population on the plot.', 'calculation', NULL, NULL, '2 000 plants', 'Area per plant = spacing between rows x spacing within a row = 1 m x 0.5 m = 0.5 square metres. Plot area = 40 m x 25 m = 1 000 square metres. Plant population = plot area / area per plant = 1 000 / 0.5 = 2 000 plants.', 'medium', '4', '2', '120', NULL, NULL, '1', NULL, NULL, 'Calculate', 'AO2', NULL, NULL, NULL),
('q_wisc_agr_b002_012', 'topic_wassce_p2_sci_agr', 'subj_wassce_int_science', 'exam_wassce', NULL, NULL, 'A farmer applies one 50 kg bag of NPK 15-15-15 fertilizer to a field. Calculate the mass of nitrogen contained in the bag.', 'calculation', NULL, NULL, '7.5 kg', 'The grade 15-15-15 means the fertilizer contains 15% nitrogen by mass. Mass of nitrogen = (15 / 100) x 50 kg = 0.15 x 50 = 7.5 kg. The same bag also contains 7.5 kg of P2O5 equivalent and 7.5 kg of K2O equivalent.', 'medium', '4', '2', '120', NULL, NULL, '1', NULL, NULL, 'Calculate', 'AO2', NULL, NULL, NULL);
CREATE TABLE _migration_459_expected_parts (id TEXT PRIMARY KEY, question_id TEXT NOT NULL, part_label TEXT NOT NULL, part_text TEXT NOT NULL, marks INTEGER NOT NULL, correct_answer TEXT NOT NULL, display_order INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS _migration_459_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _migration_459_guard;
INSERT INTO _migration_459_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM _migration_459_expected e JOIN questions q ON q.id = e.id WHERE NOT (q.topic_id IS e.topic_id AND q.subject_id IS e.subject_id AND q.exam_type_id IS e.exam_type_id AND q.paper_type_id IS e.paper_type_id AND q.past_paper_id IS e.past_paper_id AND q.question_text IS e.question_text AND q.question_type IS e.question_type AND q.round_type IS e.round_type AND q.options IS e.options AND q.correct_answer IS e.correct_answer AND q.explanation IS e.explanation AND q.difficulty IS e.difficulty AND q.points IS e.points AND q.marks IS e.marks AND q.time_limit IS e.time_limit AND q.question_number IS e.question_number AND q.section IS e.section AND q.is_compulsory IS e.is_compulsory AND q.image_url IS e.image_url AND q.syllabus_topic_id IS e.syllabus_topic_id AND q.command_word IS e.command_word AND q.assessment_objective IS e.assessment_objective AND q.source_paper_code IS e.source_paper_code AND q.source_question_number IS e.source_question_number AND q.exam_board_id IS e.exam_board_id)) AND NOT EXISTS (SELECT 1 FROM _migration_459_expected e JOIN question_content_releases r ON r.question_id = e.id WHERE NOT (r.batch_id IS 'wassce-int-science-sprint2-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Integrated Science practice; not official WAEC examination material.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) SELECT id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id FROM _migration_459_expected e WHERE NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = e.id);
INSERT INTO question_content_releases (question_id, batch_id, quality_assurance, release_channel, content_label, source_url, official_exam_board_content, feedback_enabled) SELECT e.id, 'wassce-int-science-sprint2-001', 'automated_beta', 'beta', 'Original BrillaPrep curriculum-aligned WASSCE Integrated Science practice; not official WAEC examination material.', 'https://nacca.gov.gh/secondary-education-curriculum/', 0, 1 FROM _migration_459_expected e WHERE NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = e.id);
DELETE FROM _migration_459_guard;
INSERT INTO _migration_459_guard(valid) SELECT CASE WHEN (SELECT COUNT(*) FROM questions q JOIN _migration_459_expected e ON e.id = q.id AND q.topic_id IS e.topic_id AND q.subject_id IS e.subject_id AND q.exam_type_id IS e.exam_type_id AND q.paper_type_id IS e.paper_type_id AND q.past_paper_id IS e.past_paper_id AND q.question_text IS e.question_text AND q.question_type IS e.question_type AND q.round_type IS e.round_type AND q.options IS e.options AND q.correct_answer IS e.correct_answer AND q.explanation IS e.explanation AND q.difficulty IS e.difficulty AND q.points IS e.points AND q.marks IS e.marks AND q.time_limit IS e.time_limit AND q.question_number IS e.question_number AND q.section IS e.section AND q.is_compulsory IS e.is_compulsory AND q.image_url IS e.image_url AND q.syllabus_topic_id IS e.syllabus_topic_id AND q.command_word IS e.command_word AND q.assessment_objective IS e.assessment_objective AND q.source_paper_code IS e.source_paper_code AND q.source_question_number IS e.source_question_number AND q.exam_board_id IS e.exam_board_id) = 4 AND (SELECT COUNT(*) FROM question_content_releases r JOIN _migration_459_expected e ON e.id = r.question_id WHERE r.batch_id IS 'wassce-int-science-sprint2-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Integrated Science practice; not official WAEC examination material.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1) = 4 AND (SELECT COUNT(*) FROM questions q JOIN topics t ON t.id = q.topic_id AND t.subject_id = q.subject_id JOIN _migration_459_expected e ON e.id = q.id) = 4 AND (SELECT COUNT(*) FROM structured_question_parts sp JOIN _migration_459_expected_parts p ON p.id = sp.id AND sp.id IS p.id AND sp.question_id IS p.question_id AND sp.part_label IS p.part_label AND sp.part_text IS p.part_text AND sp.marks IS p.marks AND sp.correct_answer IS p.correct_answer AND sp.display_order IS p.display_order) = 0 THEN 1 ELSE 0 END;
DROP TABLE _migration_459_guard;
DROP TABLE _migration_459_expected;
DROP TABLE _migration_459_expected_parts;
